class _DisjointSet:
    """Minimal union-find over hashable tokens used to group task run entries
    that must coalesce because they share either an ``id`` or a natural key
    ``(flow_run_id, task_key, dynamic_key)``."""

    def __init__(self) -> None:
        self._parent: dict[Any, Any] = {}

    def find(self, token: Any) -> Any:
        parent = self._parent
        parent.setdefault(token, token)
        root = token
        while parent[root] != root:
            root = parent[root]
        # Path compression
        while parent[token] != root:
            parent[token], token = root, parent[token]
        return root

    def union(self, a: Any, b: Any) -> None:
        ra, rb = self.find(a), self.find(b)
        if ra != rb:
            self._parent[ra] = rb


